import React from 'react';
import { Link } from 'react-router-dom';
import { Navbar, Nav, Container } from 'react-bootstrap';
import 'animate.css';
import './Navbar.css'; // Optional for custom styles

function NavbarComponent() {
  return (
    <Navbar
      expand="lg"
      bg="transparent"
      variant="dark"
      className="animate__animated animate__fadeIn fixed-top"
      style={{ backdropFilter: 'blur(10px)', backgroundColor: 'rgba(0, 0, 0, 0.4)' }}
    >
      <Container>
        <Navbar.Brand as={Link} to="/" className="fw-bold">
          📚 Comics World
        </Navbar.Brand>
        <Navbar.Toggle aria-controls="navbar-nav" />
        <Navbar.Collapse id="navbar-nav">
          <Nav className="ms-auto">
            <Nav.Link as={Link} to="/" className="nav-item">
              Home
            </Nav.Link>
            <Nav.Link as={Link} to="/comics" className="nav-item">
              Comics
            </Nav.Link>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
}

export default NavbarComponent;
